draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;

  // body
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();

  // arm
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2 + 40 + 20 * Math.sin(t), H/2 + 60);
  ctx.stroke();

  // hand
  ctx.beginPath();
  ctx.arc(W/2 + 40 + 20 * Math.sin(t), H/2 + 60, 10, 0, 2 * Math.PI);
  ctx.stroke();

  // leg
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 100);
  ctx.stroke();

  // other leg
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2 + 10, H/2 + 100);
  ctx.stroke();

  ctx.restore();
}
